/** Private evidence proposals. No persistent format or execution port is implemented. */
import type { CommitmentTargetV1 } from "../oath/contracts";
import type { NativeHeadV1, NativeTargetV1 } from "../oath/completion-proof";
import type { AtomicActionEnvelopeV2 } from "../application/contracts";
export interface ApplicationAuthorityPinV1 { version: 1; authorityId: string; applicationContextId: string }
export interface NativeOperationReferenceV1 { authorityId: string; operationId: string; stableIntentDigest: string; receipt: null | { repositoryRevision: number; revisionId: string } }
export interface ApplicationCommitEvidenceV1 { authority: ApplicationAuthorityPinV1; operationId: string; stableIntentDigest: string; applicationRevision: number; scopeDigest: string; publication: "confirmed" | "uncertain" | "not-confirmed"; physicalParticipants: readonly { kind: "local-data" | "shared-project-data"; snapshotDigest: string; confirmation: "observed" | "unavailable" }[] }
export type WorkflowKind = "inbox-task" | "oath-enrollment" | "oath-fulfillment" | "oath-terminal" | "phase-deletion";
export interface WorkflowEvidenceV1 { version: 1; privacy: "local-private"; kind: WorkflowKind; sourceIdentity: string; preparationDigest: string; native: readonly NativeOperationReferenceV1[]; application: readonly ApplicationCommitEvidenceV1[] }
export interface ParticipantObservationV1 { authorityId: string; operationId: string; intentDigest: string; state: "not-issued" | "confirmed" | "uncertain" | "rejected" | "unavailable" | "conflict"; basis: "native-receipt" | "filesystem-readback" | "save-promise" | "none"; receipt: null | { operationId: string; intentDigest: string; revision: number; headDigest: string } }
export interface WorkflowObservationV1 { version: 1; privacy: "local-private"; id: string; kind: WorkflowKind; sourceIdentity: string; preparationDigest: string; preparation: "confirmed" | "unconfirmed" | "uncertain"; originalIntent: "retained" | "missing"; authority: "matched" | "mismatched" | "unknown"; recovery: "intact" | "fenced" | "unknown"; source: "unchanged" | "changed" | "target-deleted" | "terminal"; proof: "sufficient" | "missing" | "not-required"; protocol: "observed-existing" | "proposed" | "unsupported"; native: readonly ParticipantObservationV1[]; application: readonly ParticipantObservationV1[] }
export interface WorkflowAnalysisV1 { readonly version: 1; readonly executable: false; readonly privacy: "local-private"; readonly id: string; readonly state: "prepared" | "partial" | "confirmed" | "uncertain" | "conflict" | "blocked" | "rejected"; readonly code: string; readonly next: "read-authority" | "identical-native-replay" | "retry-application-only" | "review" | "none"; readonly guarantee: "captured-observation-only"; readonly nativeConfirmed: readonly Readonly<{ authorityId: string; operationId: string }>[] }
export interface CoordinationCaptureV1 { version: 1; privacy: "local-private"; sourceGraphDigest: string; observations: readonly WorkflowObservationV1[] }
export interface CoordinationAnalysisV1 { readonly version: 1; readonly privacy: "local-private"; readonly executable: false; readonly sourceGraphDigest: string; readonly available: boolean; readonly reason: string; readonly inputCount: number; readonly accounting: Readonly<Record<WorkflowAnalysisV1["state"], number>>; readonly rows: readonly Readonly<{ ordinal: number; id: string; outcome: WorkflowAnalysisV1 }>[] }
export function analyzeCoordinationEvidence(capture: CoordinationCaptureV1): CoordinationAnalysisV1;
export function classifyWorkflowOutcome(evidence: WorkflowObservationV1): WorkflowAnalysisV1;
/** Unimplemented proposals; never accepted as F2 closed-synthetic ordering. */
export interface OathEnrollmentProofProposalV1 { version: 1; executable: false; session: CommitmentTargetV1["session"]; targets: readonly NativeTargetV1[]; targetSetDigest: string; enrollment: ApplicationCommitEvidenceV1; cut: NativeHeadV1; openTasks: readonly { taskId: string; taskRevision: number }[]; ownerContextPin: string; identityPin: string | null; witness: ApplicationCommitEvidenceV1 }
export interface OathFulfillmentProofProposalV1 { version: 1; executable: false; session: CommitmentTargetV1["session"]; enrollmentWitnessDigest: string; basis: "qualified-parents" | "deadline"; observationHead: NativeHeadV1 | null; qualifiedEventIds: readonly string[]; fulfilledAt: number; publication: ApplicationCommitEvidenceV1 }
export interface InboxPreparationProposalV1 { version: 1; executable: false; captureId: string; authority: ApplicationAuthorityPinV1; draftDigest: string; originalIntent: AtomicActionEnvelopeV2; native: NativeOperationReferenceV1; preparation: ApplicationCommitEvidenceV1 }
export interface InboxAcknowledgementProposalV1 { version: 1; executable: false; captureId: string; preparationDigest: string; native: NativeOperationReferenceV1; cleanup: "removed" | "retained-done" | "review-required"; publication: ApplicationCommitEvidenceV1 }
export interface PlanningPinProposalV1 { version: 1; executable: false; projectId: string; phaseId: string; application: ApplicationAuthorityPinV1; participant: "local-data" | "shared-project-data"; revision: number; digest: string }
export interface PhaseDeletionProposalV1 { version: 1; executable: false; original: PlanningPinProposalV1; assignmentBarrier: "proposed-unimplemented"; targets: readonly string[]; clearingOperations: readonly NativeOperationReferenceV1[]; finalPublication: ApplicationCommitEvidenceV1 | null }
